/// 乱击·多鹏面（武将面批 81）：手牌选项列表（SelectCards min=max=2 读
/// 两张，花色一致性在消费段校验——上游 complexCard 逐张校验同口径）。
fn same_suit_pair_options(
    core: &crate::state::GameStateCore,
    owner: PlayerId,
) -> Vec<ChoiceOption> {
    core.player(owner)
        .hand
        .iter()
        .copied()
        .map(ChoiceOption::Card)
        .collect()
}

/// 乱击两卡花色一致性校验（上游 filterCard: get.suit(card) ==
/// get.suit(ui.selected.cards[0]) 同口径）。
fn upstream_same_suit(ctx: &Ctx<'_>, cards: &[CardId]) -> bool {
    let Some(first) = cards.first() else {
        return false;
    };
    let suit = ctx.catalog.cards[*first as usize].suit;
    cards
        .iter()
        .all(|c| ctx.catalog.cards[*c as usize].suit == suit)
}

/// 羊皮卷发现类别池（swd 第十三批 v97）：上游 `get.inpile(type)` 按通用
/// type 枚举；原生按目录牌种枚举——gwent/炉石/古剑机关/食物/欢乐等
/// 专用牌种不入池（登记边界）。Tag：0=基本 1=锦囊 2=装备。
pub fn yangpijuan_class(kind: CardKind) -> Option<u8> {
    use CardKind as K;
    match kind {
        K::Sha | K::FireSha | K::LeiSha | K::Shan | K::Tao | K::Jiu | K::Hufu
        | K::Caoyao | K::Tianxianjiu => Some(0),
        K::SavageAttack
        | K::ArcheryAttack
        | K::Duel
        | K::Nullify
        | K::Le
        | K::Bing
        | K::ShanDian
        | K::Dismantle
        | K::Snatch
        | K::Chain
        | K::Wuzhong
        | K::Taoyuan
        | K::Wugu
        | K::Jiedao
        | K::WangmeiZhike
        | K::Shuigong
        | K::Fudichouxin
        | K::Chenhuodajie
        | K::HongShui
        | K::Toulianghuanzhu
        | K::Youdishenru
        | K::Geanguanhuo
        | K::Caochuanjiejian
        | K::Guiyoujie
        | K::Zhufangshenshi
        | K::Liuxinghuoyu => Some(1),
        _ if kind.equip_slot().is_some() => Some(2),
        _ => None,
    }
}

/// 宿主技能续执行机器：显式类型化状态（挂起/恢复载荷）。
#[derive(Debug, Clone)]
pub struct HostMachine {
    /// 定义键（目录技能名；String 便于快照编解码，无泄漏风险）。
    pub def_key: String,
    pub behavior: HostBehavior,
    pub owner: PlayerId,
    pub target: Option<PlayerId>,
    /// 关联卡牌（手里剑：伤害归因）。
    pub card: Option<CardId>,
    /// 关联卡牌组（思继：本次弃置的牌）。
    pub cards: Vec<CardId>,
    /// 多目标行为的目标列表（水攻）。
    pub targets: Vec<PlayerId>,
    /// 显式续行阶段（入快照；恢复后从该阶段继续）。
    pub stage: HostStage,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum HostStage {
    /// 执行行为效果。
    Act,
    /// 手里剑：等待目标选择（弃装备 / 受伤）。
    TargetChoice,
    /// 五行盘：等待选择要改属性的手牌。
    SelectCard,
    /// 五行盘：等待选择新属性（PickTag 0..=4）。
    SelectNature,
    /// 拼点：等待目标选牌。
    CompareTargetPick,
    /// 拼点：等待己方选牌。
    ComparePlayerPick,
    /// 丈八蛇矛：等待选择两张手牌。
    CardsAsk,
    /// 分舵（习嫣 jiefen）：等待选交牌目标。
    JiefenTarget,
    /// 分舵：等待目标选交出的手牌。
    JiefenTargetDiscard,
    /// 分舵：等待自己选交出的手牌。
    JiefenOwnerDiscard,
    /// 神秘果窗口（卡牌面窗口机批）：载体用牌结算后——原体上桌面重发射。
    ShenmiguoRestage,
    /// 鼠槌（equip5）：等待目标选择（攻击范围内）。
    ShuchuiTarget,
    /// 鼠槌（equip5）：目标已选定——逐张用杀循环（凤略 Yield 同型）。
    ShuchuiTargetLoop,
    /// 还人：等待选下一关武将（PickTag 下标）。
    HuanrenPick,
}

impl HostStage {
    pub const fn tag(self) -> u8 {
        match self {
            HostStage::Act => 0,
            HostStage::TargetChoice => 1,
            HostStage::SelectCard => 2,
            HostStage::SelectNature => 3,
            HostStage::CompareTargetPick => 4,
            HostStage::ComparePlayerPick => 5,
            HostStage::CardsAsk => 6,
            HostStage::JiefenTarget => 7,
            HostStage::JiefenTargetDiscard => 8,
            HostStage::JiefenOwnerDiscard => 9,
            HostStage::ShenmiguoRestage => 10,
            HostStage::ShuchuiTargetLoop => 11,
            HostStage::ShuchuiTarget => 12,
            HostStage::HuanrenPick => 13,
        }
    }
    pub fn from_tag(t: u8) -> Option<Self> {
        Some(match t {
            0 => HostStage::Act,
            1 => HostStage::TargetChoice,
            2 => HostStage::SelectCard,
            3 => HostStage::SelectNature,
            4 => HostStage::CompareTargetPick,
            5 => HostStage::ComparePlayerPick,
            6 => HostStage::CardsAsk,
            7 => HostStage::JiefenTarget,
            8 => HostStage::JiefenTargetDiscard,
            9 => HostStage::JiefenOwnerDiscard,
            10 => HostStage::ShenmiguoRestage,
            11 => HostStage::ShuchuiTargetLoop,
            12 => HostStage::ShuchuiTarget,
            13 => HostStage::HuanrenPick,
            _ => return None,
        })
    }
}

