                    // ② 失去 1 点体力
                    ctx.emit(EventData::LoseHp {
                        player: self.owner,
                        amount: 1,
                    });
                    // ③ 弃置使用者一张牌（手/装备；强制）
                    let cards: Vec<CardId> = ctx
                        .core
                        .player(user)
                        .hand
                        .iter()
                        .chain(ctx.core.player(user).equips.iter())
                        .copied()
                        .collect();
